// ============================================================
// HARD FILTER ENGINE v1.6
// n8n Code node
// Mode: Run Once for All Items
//
// Главное правило:
// если данных недостаточно — НЕ FAIL.
// ============================================================


// ============================================================
// 1. CONFIG
// ============================================================

const CONFIG = {
  version: 'v1.6',

  // Public reference configuration.
  // Customize these values for your own candidate profile before use.
  seniority: {
    enabled: false,
  },

  budget: {
    enabled: false,
    hourlyMinUsd: 0,
    fixedMinUsd: 0,
    allowSmallPaidTest: false,
  },

  experience: {
    enabled: false,
    hardMinYears: 0,
  },

  capabilities: {
    // Replace these example signals with capability gaps that are truly
    // disqualifying for your own use case.
    hardGapDomains: {
      example_domain: {
        strongSignals: [
          'REPLACE_WITH_REQUIRED_SKILL_SIGNAL_1',
          'REPLACE_WITH_REQUIRED_SKILL_SIGNAL_2',
        ],
        minSignals: 2,
      },
    },
  },

  geography: {
    allowedBroadRegions: [
      'worldwide',
      'global',
      'anywhere',
    ],

    // Replace with your own eligible region/city signals.
    allowedLocationSignals: [
      'YOUR_ALLOWED_REGION',
      'YOUR_CITY',
    ],

    // Add only locations that are explicitly incompatible with your profile.
    blockedLocationSignals: [
      'YOUR_BLOCKED_REGION',
    ],

    ambiguousRegions: [
      'emea',
      'remote',
      'international',
      'multiple locations',
    ],
  },

  languages: {
    // Add languages that satisfy mandatory language requirements for you.
    allowedLanguages: [
      'english',
    ],
  },

  // Unknown work authorization must not be treated as a hard failure
  // unless explicit logic is configured.
  workAuthorization: {
    enabled: false,
  },
};


// Один timestamp на весь текущий запуск.
const RUN_AT = new Date();
const RUN_AT_ISO = RUN_AT.toISOString();


// ============================================================
// 2. BASIC HELPERS
// ============================================================

function str(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value);
}


function lower(value) {
  return str(value)
    .toLowerCase()
    .trim();
}


function upper(value) {
  return str(value)
    .toUpperCase()
    .trim();
}


function num(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : null;
}


function boolTrue(value) {
  return (
    value === true ||
    value === 'true' ||
    value === 1 ||
    value === '1'
  );
}


function boolFalse(value) {
  return (
    value === false ||
    value === 'false' ||
    value === 0 ||
    value === '0'
  );
}


function addReason(reasons, reason) {
  reasons.add(reason);
}


// ============================================================
// 3. SMALL PAID TEST
//
// Пока выключено в CONFIG.
// Функция оставлена на будущее.
// ============================================================

function isSmallPaidTask(text) {
  return (
    /\bpaid\s+(test|trial|screening|assessment)\b/i.test(text) ||
    /\bdiscovery\s+(task|project|phase|call)\b/i.test(text) ||
    /\bsmall\s+(audit|task)\b/i.test(text) ||
    /\bproof\s+of\s+concept\b/i.test(text) ||
    /\bpoc\b/i.test(text)
  );
}


// ============================================================
// 4. SENIORITY
// Reason: SENIORITY_TOO_HIGH
//
// Employment:
// Senior / Staff / Principal / Lead / Head / Director.
//
// Project:
// слово Senior само по себе НЕ режем.
//
// v1.1:
// добавлено распознавание senior-role внутри description,
// но с защитой для вакансий типа
// "junior through senior" / "all levels".
// ============================================================

function hasHighSeniority(p) {
  if (!CONFIG.seniority?.enabled) {
    return false;
  }

  const opportunityType =
    lower(p.opportunity_type);


  if (opportunityType !== 'employment') {
    return false;
  }


  const title =
    lower(p.title);

  const level =
    lower(p.experience_level);

  const description =
    lower(p.description);


  // ----------------------------------------------------------
  // 1. Structured experience level
  // ----------------------------------------------------------

  if (
    /\b(senior|staff|principal|head|director)\b/i.test(level)
  ) {
    return true;
  }


  // ----------------------------------------------------------
  // 2. Explicit seniority in title
  // ----------------------------------------------------------

  if (
    /\b(senior|staff|principal|head|director)\b/i.test(title)
  ) {
    return true;
  }


  // ----------------------------------------------------------
  // 3. Lead BEFORE role
  //
  // Lead Engineer
  // Lead Developer
  // Technical Lead
  // ----------------------------------------------------------

  if (
    /\b(team|tech|technical)\s+lead\b/i.test(title)
  ) {
    return true;
  }


  if (
    /\blead\s+(engineer|developer|architect|manager|scientist|designer|product|data|ai|ml|software|frontend|backend|full[- ]?stack|qa)\b/i.test(title)
  ) {
    return true;
  }


  // ----------------------------------------------------------
  // 4. Lead AFTER role
  //
  // NEW in v1.4
  //
  // QA Engineer Lead
  // Software Engineer Lead
  // Developer Lead
  // ----------------------------------------------------------

  if (
    /\b(engineer|developer|architect|manager|scientist|designer)\s+lead\b/i.test(title)
  ) {
    return true;
  }


  // ----------------------------------------------------------
  // 5. Explicit architect employment role
  // ----------------------------------------------------------

  if (
    /\b(solution|solutions|software|enterprise|cloud|ai|data)\s+architect\b/i.test(title)
  ) {
    return true;
  }


  // ----------------------------------------------------------
  // 6. Multi-level role guard
  //
  // "We hire from junior through senior"
  // "Open on level"
  // "Juniors are welcome"
  //
  // Не режем такие вакансии только из-за слова senior
  // внутри description.
  // ----------------------------------------------------------

  const explicitlyMultiLevel =
    (
      /\b(open\s+on\s+level|open\s+to\s+all\s+levels)\b/i.test(description) ||

      /\b(junior|juniors)\b.{0,80}\b(senior|all\s+levels)\b/i.test(description) ||

      /\bsenior\b.{0,80}\b(junior|juniors)\b/i.test(description) ||

      /\bhire\s+from\s+junior\s+(?:through|to)\s+senior\b/i.test(description) ||

      /\bjuniors?\s+(?:are\s+)?(?:welcome|encouraged)\b/i.test(description)
    );


  if (explicitlyMultiLevel) {
    return false;
  }


  // ----------------------------------------------------------
  // 7. Explicit senior role inside description
  // ----------------------------------------------------------

  const seniorRolePatterns = [

  // "We are looking for a Senior Engineer"
  /\b(?:we\s+are\s+|we're\s+)?(?:looking|hiring|seeking)\s+for\s+(?:an?\s+)?(?:experienced\s+)?(?:senior|staff|principal|lead|head|director)\s+(?:engineer|developer|architect|manager|scientist|designer|specialist|consultant|analyst)\b/i,

  // "We need a Senior Engineer"
  /\b(?:we\s+need|seeking)\s+(?:an?\s+)?(?:senior|staff|principal|lead|head|director)\s+(?:engineer|developer|architect|manager|scientist|designer|specialist|consultant|analyst)\b/i,

  // "This role is at the senior level"
  /\bthis\s+(?:role|position)\s+is\s+(?:at\s+)?(?:the\s+)?(senior|staff|principal)\s+level\b/i,

  // "Need someone at the senior level"
  /\bneed\s+someone\s+at\s+(?:the\s+)?(senior|staff|principal)\s+level\b/i,

  // "Founding QA Engineer (Lead)"
  // "Software Engineer Lead"
  /\b(?:founding\s+)?(?:qa\s+)?(?:engineer|developer|architect|manager|scientist|designer)\s*(?:\(\s*)?lead(?:\s*\))?\b/i,
];


  if (
    seniorRolePatterns.some(
      pattern => pattern.test(description)
    )
  ) {
    return true;
  }


  return false;
}


// ============================================================
// 5. MUST-HAVE EXPERIENCE
// Reason: MUST_HAVE_SKILL_GAP
//
// Не режем preferred / nice to have.
//
// v1.2:
// дополнительно ловим:
// - 5+ years of deep, production async Python
// - 5 + years of full-stack delivery skills
// - 8+ years building production systems
// - 5+ years in Data Science
//
// При этом не принимаем возраст компании за опыт кандидата.
// ============================================================

function hasHardExperienceGap(p, text) {
  if (!CONFIG.experience?.enabled) {
    return false;
  }

  const structuredYears =
    num(p.experience_years_min);


  // ----------------------------------------------------------
  // 1. Structured minimum
  // ----------------------------------------------------------

  if (
    structuredYears !== null &&
    structuredYears >= CONFIG.experience.hardMinYears
  ) {
    return true;
  }


  // Работаем по строкам / коротким фрагментам,
  // чтобы не связывать число лет с чем-то далеко в тексте.
  const parts = text
    .split(/[\n.!?;]+/)
    .map(s => s.trim())
    .filter(Boolean);


  const optionalPattern =
    /\b(preferred|nice\s+to\s+have|ideally|would\s+be\s+a\s+plus|plus|advantage|bonus|desirable|optional)\b/i;


  // Защита от истории самой компании:
  // "founded 5+ years ago" не является требованием к кандидату.
  const companyAgePattern =
    /\b(founded|established|operating|in\s+business)\b.{0,40}\b\d{1,2}\s*\+\s*years?\b/i;


  for (const part of parts) {

    // Optional → не hard fail.
    if (optionalPattern.test(part)) {
      continue;
    }


    // Возраст / история компании → не требование.
    if (companyAgePattern.test(part)) {
      continue;
    }


    // --------------------------------------------------------
    // Pattern A
    //
    // 5+ years of deep, production async Python
    // 5+ years of full-stack delivery skills
    // 8+ years building production systems
    // 6+ years relevant software engineering experience
    //
    // Разрешаем до 80 символов между "years" и
    // словом, подтверждающим experience context.
    // --------------------------------------------------------

    const plusYearsMatch =
      part.match(
        /\b(\d{1,2})\s*\+\s*years?\s+(?:of\s+)?[^.!?\n]{0,80}?\b(experience|engineering|engineer|development|developer|delivery|building|working|production|python|react|typescript|backend|frontend|full[- ]?stack|software|data\s+science|applied\s+ai|machine\s+learning|ml|technical)\b/i
      );


    if (plusYearsMatch) {
      const years =
        Number(plusYearsMatch[1]);


      if (
        Number.isFinite(years) &&
        years >= CONFIG.experience.hardMinYears
      ) {
        return true;
      }
    }


    // --------------------------------------------------------
    // Pattern B
    //
    // 5+ years in Data Science
    // 8+ years in technical roles
    // --------------------------------------------------------

    const yearsInMatch =
      part.match(
        /\b(\d{1,2})\s*\+\s*years?\s+in\s+[a-z]/i
      );


    if (yearsInMatch) {
      const years =
        Number(yearsInMatch[1]);


      if (
        Number.isFinite(years) &&
        years >= CONFIG.experience.hardMinYears
      ) {
        return true;
      }
    }


    // --------------------------------------------------------
    // Pattern C
    //
    // at least 5 years
    // minimum 5 years
    // --------------------------------------------------------

    const minimumMatch =
      part.match(
        /\b(?:at\s+least|minimum\s+of|minimum|min\.?)\s+(\d{1,2})\s*\+?\s*years?\b/i
      );


    if (minimumMatch) {
      const years =
        Number(minimumMatch[1]);


      if (
        Number.isFinite(years) &&
        years >= CONFIG.experience.hardMinYears
      ) {
        return true;
      }
    }


    // --------------------------------------------------------
    // Pattern D
    //
    // must have 5 years
    // requires 5+ years
    // --------------------------------------------------------

    const requiredMatch =
      part.match(
        /\b(?:requires?|required|must\s+have)\s+(\d{1,2})\s*\+?\s*years?\b/i
      );


    if (requiredMatch) {
      const years =
        Number(requiredMatch[1]);


      if (
        Number.isFinite(years) &&
        years >= CONFIG.experience.hardMinYears
      ) {
        return true;
      }
    }


    // --------------------------------------------------------
    // Pattern E
    //
    // 5 years of experience
    // 5 years' experience
    // --------------------------------------------------------

    const normalYearsMatch =
      part.match(
        /\b(\d{1,2})\s+years?(?:['’]\s*)?(?:of\s+)?experience\b/i
      );


    if (normalYearsMatch) {
      const years =
        Number(normalYearsMatch[1]);


      if (
        Number.isFinite(years) &&
        years >= CONFIG.experience.hardMinYears
      ) {
        return true;
      }
    }
  }


  return false;
}

// ============================================================
// 5B. MUST-HAVE CAPABILITY GAP v2
// Reason: MUST_HAVE_SKILL_GAP
//
// UNKNOWN ≠ FAIL
// preferred / nice-to-have / bonus / optional ≠ FAIL
// одного сигнала недостаточно
// ============================================================

function escapeRegExp(value) {
  return str(value)
    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}


function normalizeCapabilityText(value) {
  return lower(value)
    .replace(/[’‘]/g, "'")
    .replace(/[–—]/g, '-')
    .replace(/&amp;/gi, '&')
    .replace(/\r/g, '');
}


function capabilityTextHasSignal(text, signal) {
  const normalizedText =
    normalizeCapabilityText(text);

  const normalizedSignal =
    normalizeCapabilityText(signal);

  if (!normalizedSignal) {
    return false;
  }

  const signalPattern =
    normalizedSignal
      .split(/\s+/)
      .map(part => escapeRegExp(part))
      .join('\\s+');

  const regex =
    new RegExp(
      `(^|[^a-z0-9])${signalPattern}([^a-z0-9]|$)`,
      'i'
    );

  return regex.test(normalizedText);
}


function cleanRequirementHeading(line) {
  return normalizeCapabilityText(line)
    .replace(/<[^>]+>/g, ' ')
    .replace(/^\s*#{1,6}\s*/, '')
    .replace(/[*_`]/g, '')
    .replace(/^\s*[-•]\s*/, '')
    .replace(/:\s*$/, '')
    .replace(/\s+/g, ' ')
    .trim();
}


function isOptionalCapabilityLine(line) {
  const t =
    normalizeCapabilityText(line);

  return (
    /\bpreferred\b/i.test(t) ||
    /\bnice\s+to\s+have\b/i.test(t) ||
    /\bgood\s+to\s+have\b/i.test(t) ||
    /\bbonus(?:\s+points?)?\b/i.test(t) ||
    /\boptional\b/i.test(t) ||
    /\badvantage\b/i.test(t) ||
    /\bwould\s+be\s+a\s+plus\b/i.test(t) ||
    /\bis\s+a\s+plus\b/i.test(t) ||
    /\bare\s+a\s+plus\b/i.test(t) ||
    /\bas\s+a\s+plus\b/i.test(t)
  );
}


function getHardRequirementText(p, text) {
  const description =
    str(p.description || text)
      .replace(/\r/g, '');

  if (!description.trim()) {
    return '';
  }

  const lines =
    description.split('\n');

  const startHeadingPattern =
    /^(?:required\s+(?:skills|qualifications|experience)|requirements?(?:\s*(?:&|and)\s*qualifications)?|qualifications|core\s+qualifications|mandatory\s+requirements|must[- ]haves?|what\s+we(?:'re| are)\s+looking\s+for|what\s+you(?:'ll| will)\s+need|what\s+you\s+bring)$/i;

  const stopHeadingPattern =
    /^(?:preferred(?:\s+(?:qualifications|skills|experience))?|nice\s+to\s+haves?|good\s+to\s+haves?|bonus(?:\s+points?)?|benefits|what\s+we\s+offer|why\s+join|why\s+this\s+role|responsibilities|key\s+responsibilities|what\s+you(?:'ll| will)\s+do|your\s+role|your\s+impact|about\s+the\s+role|company\s+overview|about\s+us|how\s+to\s+apply|next\s+steps|what\s+success\s+looks\s+like)$/i;

  const sections = [];

  let currentSection = null;


  for (const line of lines) {
    const heading =
      cleanRequirementHeading(line);

    if (startHeadingPattern.test(heading)) {
      if (
        currentSection &&
        currentSection.length
      ) {
        sections.push(
          currentSection.join('\n')
        );
      }

      currentSection = [];

      continue;
    }


    if (
      currentSection &&
      stopHeadingPattern.test(heading)
    ) {
      if (currentSection.length) {
        sections.push(
          currentSection.join('\n')
        );
      }

      currentSection = null;

      continue;
    }


    if (currentSection) {
      if (!isOptionalCapabilityLine(line)) {
        currentSection.push(line);
      }
    }
  }


  if (
    currentSection &&
    currentSection.length
  ) {
    sections.push(
      currentSection.join('\n')
    );
  }


  const mandatoryPattern =
    /\b(must\s+have|required(?:\s+(?:skills|qualifications|experience))?|mandatory|proficiency\s+in|expertise\s+in|deep\s+(?:hands[- ]on\s+)?experience|hands[- ]on\s+experience|we(?:'re| are)\s+looking\s+for.{0,100}\bexperience\b|looking\s+for.{0,100}\bwith\b.{0,80}\bexperience\b)\b/i;


  const fallbackClauses =
    description
      .split(/[\n.!?;]+/)
      .map(part => part.trim())
      .filter(Boolean)
      .filter(part =>
        !isOptionalCapabilityLine(part) &&
        mandatoryPattern.test(
          normalizeCapabilityText(part)
        )
      );


  return [
    ...sections,
    ...fallbackClauses,
  ]
    .filter(Boolean)
    .join('\n');
}


function hasHardCapabilityGap(p, text) {
  const requirementText =
    getHardRequirementText(p, text);


  if (!requirementText.trim()) {
    return false;
  }


  const domains =
    CONFIG.capabilities?.hardGapDomains ?? {};


  for (const domain of Object.values(domains)) {
    const signals =
      Array.isArray(domain.strongSignals)
        ? domain.strongSignals
        : [];


    const minSignals =
      Number.isFinite(domain.minSignals)
        ? domain.minSignals
        : 2;


    let hitCount = 0;


    for (const signal of signals) {
      if (
        capabilityTextHasSignal(
          requirementText,
          signal
        )
      ) {
        hitCount += 1;
      }


      if (hitCount >= minSignals) {
        return true;
      }
    }
  }


  return false;
}


// ============================================================
// 6. BUDGET
// Reason: BUDGET_TOO_LOW
//
// Hourly < $15/h → FAIL
// Fixed < $50 → FAIL
//
// Только USD.
// Неизвестная валюта / FX → НЕ FAIL.
// ============================================================

function isBudgetTooLow(p, text) {
  if (!CONFIG.budget?.enabled) {
    return false;
  }

  const currency =
    upper(p.currency);


  // Пока не делаем автоматическую конвертацию валют.
  if (currency !== 'USD') {
    return false;
  }


  const rateType =
    lower(p.rate_type);

  const min =
    num(p.budget_min);

  const max =
    num(p.budget_max);

  const budgetText =
    lower(p.budget_text);


  // ----------------------------------------------------------
  // HOURLY
  // ----------------------------------------------------------

  if (rateType === 'hourly') {
    const lessThanMatch =
      budgetText.match(
        /less\s+than\s+(?:usd\s*)?\$?\s*([\d.]+)/
      );


    if (lessThanMatch) {
      const cap =
        Number(lessThanMatch[1]);


      if (
        Number.isFinite(cap) &&
        cap <= CONFIG.budget.hourlyMinUsd
      ) {
        return true;
      }
    }


    // Если даже максимальная ставка ниже минимума.
    if (
      max !== null &&
      max < CONFIG.budget.hourlyMinUsd
    ) {
      return true;
    }


    return false;
  }


  // ----------------------------------------------------------
  // FIXED
  // ----------------------------------------------------------

  if (rateType === 'fixed') {
    if (
      CONFIG.budget.allowSmallPaidTest &&
      isSmallPaidTask(text)
    ) {
      return false;
    }


    const lessThanMatch =
      budgetText.match(
        /less\s+than\s+(?:usd\s*)?\$?\s*([\d.]+)/
      );


    if (lessThanMatch) {
      const cap =
        Number(lessThanMatch[1]);


      if (
        Number.isFinite(cap) &&
        cap <= CONFIG.budget.fixedMinUsd
      ) {
        return true;
      }
    }


    if (
      max !== null &&
      max < CONFIG.budget.fixedMinUsd
    ) {
      return true;
    }
  }


  return false;
}


// ============================================================
// 7. EXPIRED
// Reason: EXPIRED
// ============================================================

function isExpired(p) {
  if (p.expires_at) {
    const expires =
      new Date(p.expires_at);


    if (
      !Number.isNaN(expires.getTime()) &&
      expires < RUN_AT
    ) {
      return true;
    }
  }


  const sf =
    p.source_flags ?? {};

  const raw =
    p.raw_data ?? {};


  if (
    boolTrue(sf.expired) ||
    boolTrue(raw.expired)
  ) {
    return true;
  }


  const sourceStatus =
    lower(
      raw.status ??
      sf.status ??
      sf.project_status
    );


  if (sourceStatus === 'expired') {
    return true;
  }


  return false;
}


// ============================================================
// 8. FILLED / CLOSED / INACTIVE
// Reason: FILLED_OR_CLOSED
// ============================================================

function isFilledOrClosed(p) {
  const sf =
    p.source_flags ?? {};

  const raw =
    p.raw_data ?? {};


  if (
    boolTrue(sf.author_says_filled) ||
    boolTrue(sf.filled) ||
    boolTrue(raw.filled) ||

    boolTrue(sf.closed) ||
    boolTrue(raw.closed) ||

    boolTrue(sf.archived) ||
    boolTrue(raw.archived) ||

    boolTrue(sf.frozen) ||
    boolTrue(raw.frozen) ||

    boolFalse(sf.open) ||
    boolFalse(raw.open) ||

    boolFalse(sf.active) ||
    boolFalse(raw.active)
  ) {
    return true;
  }


  if (
    sf.deleted_at ||
    raw.deleted_at
  ) {
    return true;
  }


  const sourceStatus =
    lower(
      raw.status ??
      sf.status ??
      sf.project_status
    );


  const closedStatuses = [
    'filled',
    'closed',
    'frozen',
    'archived',
    'cancelled',
    'canceled',
    'inactive',
    'deleted',
  ];


  return closedStatuses.includes(
    sourceStatus
  );
}



// ============================================================
// 9. GEOGRAPHY
// Reason: GEO_INELIGIBLE
//
// Public reference implementation.
// Candidate-specific region rules are intentionally excluded.
// UNKNOWN ≠ FAIL.
// ============================================================

function normalizeGeo(value) {
  return lower(value)
    .replace(/[–—]/g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}


function geoMatchesAny(value, signals) {
  const v = normalizeGeo(value);

  return (signals ?? [])
    .map(normalizeGeo)
    .filter(Boolean)
    .some(signal =>
      v === signal ||
      v.includes(signal)
    );
}


function getTextGeoDecision(text) {
  const t = normalizeGeo(text);

  if (
    geoMatchesAny(
      t,
      CONFIG.geography.blockedLocationSignals
    )
  ) {
    return 'ineligible';
  }

  if (
    geoMatchesAny(
      t,
      CONFIG.geography.allowedBroadRegions
    ) ||
    geoMatchesAny(
      t,
      CONFIG.geography.allowedLocationSignals
    )
  ) {
    return 'eligible';
  }

  return 'unknown';
}


function getStructuredGeoDecision(p) {
  if (!Array.isArray(p.remote_regions)) {
    return 'unknown';
  }

  const regions = p.remote_regions
    .map(normalizeGeo)
    .filter(Boolean);

  if (!regions.length) {
    return 'unknown';
  }

  const hasAllowed = regions.some(region =>
    geoMatchesAny(
      region,
      CONFIG.geography.allowedBroadRegions
    ) ||
    geoMatchesAny(
      region,
      CONFIG.geography.allowedLocationSignals
    )
  );

  if (hasAllowed) {
    return 'eligible';
  }

  const hasAmbiguous = regions.some(region =>
    geoMatchesAny(
      region,
      CONFIG.geography.ambiguousRegions
    )
  );

  if (hasAmbiguous) {
    return 'unknown';
  }

  const blockedSignals =
    CONFIG.geography.blockedLocationSignals ?? [];

  if (
    blockedSignals.length > 0 &&
    regions.every(region =>
      geoMatchesAny(region, blockedSignals)
    )
  ) {
    return 'ineligible';
  }

  return 'unknown';
}


function geographyIneligible(p, text) {
  const textDecision =
    getTextGeoDecision(text);

  const structuredDecision =
    getStructuredGeoDecision(p);

  if (textDecision === 'ineligible') {
    return true;
  }

  if (textDecision === 'eligible') {
    return false;
  }

  return structuredDecision === 'ineligible';
}


// ============================================================
// 11. LANGUAGES
// Reason: LANGUAGE_INELIGIBLE
//
// Public reference implementation.
// Configure allowedLanguages for your own profile.
// Optional / preferred language requirements do not hard-fail.
// ============================================================

function languageIneligible(text) {
  const clauses = str(text)
    .split(/[\n.!?;,]+/)
    .map(part => part.trim())
    .filter(Boolean);

  const optionalPattern =
    /\b(preferred|nice\s+to\s+have|would\s+be\s+a\s+plus|plus|advantage|bonus|desirable|valuable|optional)\b/i;

  const allowedLanguages =
    (CONFIG.languages?.allowedLanguages ?? [])
      .map(lower)
      .filter(Boolean);

  const languagePatterns = [
    /\b([a-z][a-z-]{2,})\s+language\s+(?:is\s+)?(?:required|mandatory|essential)\b/ig,
    /\b([a-z][a-z-]{2,})\s+speakers?\s+(?:is\s+|are\s+)?(?:required|mandatory|needed|essential)\b/ig,
    /\b(?:must|required\s+to|need\s+to)\s+(?:speak|read|write)\s+([a-z][a-z-]{2,})\b/ig,
    /\bfluency\s+in\s+([a-z][a-z-]{2,})\b/ig,
    /\b(?:must|need\s+to|required\s+to)\s+be\s+fluent\s+in\s+([a-z][a-z-]{2,})\b/ig,
    /\bnative(?:[- ]level)?\s+([a-z][a-z-]{2,})\s+speakers?\b/ig,
    /\b([a-z][a-z-]{2,})\s+language\s+proficiency\s+(?:is\s+)?(?:required|mandatory|essential)\b/ig,
  ];

  for (const clause of clauses) {
    if (optionalPattern.test(clause)) {
      continue;
    }

    for (const pattern of languagePatterns) {
      pattern.lastIndex = 0;

      let match;

      while ((match = pattern.exec(clause)) !== null) {
        const language = lower(match[1]);

        if (!allowedLanguages.includes(language)) {
          return true;
        }
      }
    }

    const explicitRequirement = clause.match(
      /\blanguage\s+(?:requirement|required)\s*[:\-]\s*([a-z][a-z-]{2,})\b/i
    );

    if (explicitRequirement) {
      const language =
        lower(explicitRequirement[1]);

      if (!allowedLanguages.includes(language)) {
        return true;
      }
    }
  }

  return false;
}


// ============================================================
// 12. WORK FORMAT
// Reason: WORK_FORMAT_INCOMPATIBLE
//
// remote / flexible / unknown → PASS
//
// onsite / hybrid:
// configured local locations → PASS
// another explicit onsite/hybrid location → FAIL
// location = null → PASS
// ============================================================

function workFormatIncompatible(p) {
  const mode =
    lower(p.work_mode);

  const location =
    lower(p.location);

  const description =
    lower(p.description)
      .replace(/[–—]/g, '-');


  const isLocalLocation = (value) => {
    return geoMatchesAny(
      value,
      CONFIG.geography.allowedLocationSignals
    );
  };


  // ----------------------------------------------------------
  // 1. EXPLICIT FORMAT + LOCATION IN DESCRIPTION
  //
  // NEW in v1.4
  //
  // Example:
  //
  // "This is a full-time, on-site position
  //  based in New York, NY"
  //
  // Текст вакансии имеет приоритет над structured metadata.
  // ----------------------------------------------------------

  const explicitTextPatterns = [

    /\b(?:this\s+is\s+)?(?:a\s+)?(?:full[- ]time\s*,?\s*)?(on[- ]?site|onsite|hybrid)\s+(?:position|role|job)\s+(?:(?:based|located)\s+in|in)\s+([^\n.;]+)/i,

    /\b(on[- ]?site|onsite|hybrid)\s+(?:position|role|job)\b[^\n.;]{0,80}\b(?:based|located)\s+in\s+([^\n.;]+)/i,
  ];


  for (const pattern of explicitTextPatterns) {
    const match =
      description.match(pattern);


    if (!match) {
      continue;
    }


    const textLocation =
      lower(match[2]);


    // If the text explicitly names an allowed local location,
    // treat the format as compatible.
    if (
      textLocation &&
      isLocalLocation(textLocation)
    ) {
      return false;
    }


    // Есть явная onsite/hybrid location,
    // и она не наша локальная.
    if (textLocation) {
      return true;
    }
  }


  // ----------------------------------------------------------
  // 2. EXPLICIT ONSITE/HYBRID IN TEXT,
  //    BUT LOCATION IS ONLY STRUCTURED
  // ----------------------------------------------------------

  const explicitNonRemoteFormat =
    /\b(on[- ]?site|onsite|hybrid)\s+(?:position|role|job)\b/i.test(
      description
    );


  if (explicitNonRemoteFormat) {

    // Нет надёжной location → не додумываем.
    if (
      !location ||
      location === 'remote' ||
      location === 'unknown'
    ) {
      return false;
    }


    return !isLocalLocation(location);
  }


  // ----------------------------------------------------------
  // 3. STRUCTURED MODE
  //
  // Если текст не дал более сильного сигнала,
  // используем canonical work_mode.
  // ----------------------------------------------------------

  if (
    mode === 'remote' ||
    mode === 'flexible' ||
    mode === 'unknown' ||
    !mode
  ) {
    return false;
  }


  // Нет location → не додумываем.
  if (!location) {
    return false;
  }


  if (
    (mode === 'onsite' || mode === 'hybrid') &&
    !isLocalLocation(location)
  ) {
    return true;
  }


  return false;
}


// ============================================================
// 13. NO GUARANTEED PAY
// Reason: NO_GUARANTEED_PAY
// ============================================================

function noGuaranteedPay(text) {
  const clauses = str(text)
    .split(/[\n.!?;]+/)
    .map(part => part.trim())
    .filter(Boolean);

  const hardPatterns = [
    /\bcommission[- ]only\b/i,
    /\bequity[- ]only\b/i,
    /\bno\s+base\s+(salary|pay|compensation)\b/i,
    /\bcompensation\s+(?:is|will\s+be)\s+commission\b/i,
  ];

  for (const clause of clauses) {

    // Явные модели без гарантированной оплаты.
    if (
      hardPatterns.some(
        pattern => pattern.test(clause)
      )
    ) {
      return true;
    }

    // ----------------------------------------------------------
    // UNPAID
    // ----------------------------------------------------------

    if (/\bunpaid\b/i.test(clause)) {
      const negatedUnpaid =
        /\b(?:not|never)\b.{0,120}\bunpaid\b/i.test(clause) ||
        /\b(?:don['’]?t|doesn['’]?t|didn['’]?t|won['’]?t|wouldn['’]?t|isn['’]?t|aren['’]?t)\b.{0,120}\bunpaid\b/i.test(clause) ||
        /\bno\s+unpaid\b/i.test(clause) ||
        /\bunpaid\b.{0,80}\b(?:is|are|will\s+be)?\s*(?:not|never)\s+(?:required|requested|expected|asked)\b/i.test(clause);

      if (!negatedUnpaid) {
        return true;
      }
    }

    // ----------------------------------------------------------
    // VOLUNTEER
    // ----------------------------------------------------------

    if (/\bvolunteer\b/i.test(clause)) {
      const negatedVolunteer =
        /\b(?:not|never)\b.{0,80}\bvolunteer\b/i.test(clause) ||
        /\bno\s+volunteer\b/i.test(clause);

      if (!negatedVolunteer) {
        return true;
      }
    }
  }

  return false;
}

// ============================================================
// 14. PLATFORM ELIGIBILITY
// Reason: PLATFORM_INELIGIBLE
// ============================================================

function platformIneligible(p, text) {
  const sf =
    p.source_flags ?? {};

  const raw =
    p.raw_data ?? {};


  if (
    boolFalse(sf.can_bid) ||
    boolFalse(sf.canBid) ||
    boolFalse(raw.can_bid) ||
    boolFalse(raw.canBid) ||

    boolFalse(sf.can_apply) ||
    boolFalse(sf.canApply) ||
    boolFalse(raw.can_apply) ||
    boolFalse(raw.canApply)
  ) {
    return true;
  }


  if (
    boolTrue(sf.invitation_only) ||
    boolTrue(raw.invitation_only)
  ) {
    return true;
  }


  const patterns = [
    /\bcannot\s+bid\b/i,
    /\bcan't\s+bid\b/i,
    /\bcannot\s+apply\b/i,
    /\bcan't\s+apply\b/i,
    /\binvitation[- ]only\b/i,
    /\bclosed\s+to\s+your\s+(region|account)\b/i,
  ];


  return patterns.some(
    pattern => pattern.test(text)
  );
}


// ============================================================
// 15. MAIN ENGINE
// ============================================================

return items.map(item => {
  const p =
    item.json ?? {};


  const reasons =
    new Set();


  const text = [
    p.title,
    p.description,
    p.budget_text,
    p.location,
  ]
    .filter(Boolean)
    .join('\n');


  // ----------------------------------------------------------
  // 1. SENIORITY
  // ----------------------------------------------------------

  if (hasHighSeniority(p)) {
    addReason(
      reasons,
      'SENIORITY_TOO_HIGH'
    );
  }


  // ----------------------------------------------------------
  // 2. MUST-HAVE EXPERIENCE
  // ----------------------------------------------------------

  if (
  hasHardExperienceGap(p, text) ||
  hasHardCapabilityGap(p, text)
) {
  addReason(
    reasons,
    'MUST_HAVE_SKILL_GAP'
  );
}


  // ----------------------------------------------------------
  // 3. BUDGET
  // ----------------------------------------------------------

  if (isBudgetTooLow(p, text)) {
    addReason(
      reasons,
      'BUDGET_TOO_LOW'
    );
  }


  // ----------------------------------------------------------
  // 4. EXPIRED
  // ----------------------------------------------------------

  if (isExpired(p)) {
    addReason(
      reasons,
      'EXPIRED'
    );
  }


  // ----------------------------------------------------------
  // 5. FILLED / CLOSED
  // ----------------------------------------------------------

  if (isFilledOrClosed(p)) {
    addReason(
      reasons,
      'FILLED_OR_CLOSED'
    );
  }


  // ----------------------------------------------------------
  // 6. GEOGRAPHY
  // ----------------------------------------------------------

  if (geographyIneligible(p, text)) {
  addReason(
    reasons,
    'GEO_INELIGIBLE'
  );
}


  // ----------------------------------------------------------
  // 7. WORK AUTHORIZATION
  // ----------------------------------------------------------
  //
  // Пока намеренно НЕ ставим FAIL.
  //
  // eligibility неизвестна →
  // Hard Filter не имеет права додумывать.
  // ----------------------------------------------------------

  if (CONFIG.workAuthorization.enabled) {
    // Reserved for future logic.
  }


  // ----------------------------------------------------------
  // 8. LANGUAGE
  // ----------------------------------------------------------

  if (languageIneligible(text)) {
    addReason(
      reasons,
      'LANGUAGE_INELIGIBLE'
    );
  }


  // ----------------------------------------------------------
  // 9. WORK FORMAT
  // ----------------------------------------------------------

  if (workFormatIncompatible(p)) {
    addReason(
      reasons,
      'WORK_FORMAT_INCOMPATIBLE'
    );
  }


  // ----------------------------------------------------------
  // 10. NO GUARANTEED PAY
  // ----------------------------------------------------------

  if (noGuaranteedPay(text)) {
    addReason(
      reasons,
      'NO_GUARANTEED_PAY'
    );
  }


  // ----------------------------------------------------------
  // 11. PLATFORM RESTRICTION
  // ----------------------------------------------------------

  if (platformIneligible(p, text)) {
    addReason(
      reasons,
      'PLATFORM_INELIGIBLE'
    );
  }


  // ----------------------------------------------------------
  // RESULT
  // ----------------------------------------------------------

  const hardFilterReasons =
    [...reasons];


  return {
    ...item,

    json: {
      ...p,

      hard_filter_status:
        hardFilterReasons.length > 0
          ? 'fail'
          : 'pass',

      hard_filter_reasons:
        hardFilterReasons,

      hard_filter_version:
        CONFIG.version,

      hard_filtered_at:
        RUN_AT_ISO,
    },
  };
});
